css:
.ax{
  --bg:#ffffff; --fg:#0f1720; --body:#2a343d; --muted:#5b6670; --rule:#dfe5ea; --panel:#f3f6f8;
  --accent:#0b6b7a; --hot:#b42318; --bar:#8aa0ad; --ref:#c4ccd2; --strip:#0f1720; --strip-fg:#ffffff;
  --note-bg:#fff7e0; --note-bd:#b08400; --note-fg:#4d3b00; --link:#0b6b7a; --key:#e8f2f4;
  --font:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;
;}html.dark .ax{
  --bg:#0e1419; --fg:#eef2f5; --body:#c9d2d9; --muted:#97a3ad; --rule:#2b363f; --panel:#161e25;
  --accent:#5cc0d0; --hot:#f2766b; --bar:#6f8795; --ref:#4a5963; --strip:#000000; --strip-fg:#ffffff;
  --note-bg:#2a2410; --note-bd:#b08400; --note-fg:#f0dca0; --link:#5cc0d0; --key:#14262b; color-scheme:dark;}.ax{color:var(--fg);font-family:var(--font)}
.ax .kick{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);font-weight:700}
.ax h1{font-size:clamp(28px,6vw,40px);line-height:1.12;margin:12px 0 16px;text-wrap:balance;color:var(--fg)}
.ax .lede{font-size:19px;line-height:1.55;color:var(--body);margin:0 0 14px}
.ax h2{font-size:24px;line-height:1.25;margin:48px 0 12px;text-wrap:balance;color:var(--fg)}
.ax h3{font-size:17px;margin:22px 0 6px;color:var(--fg)}
.ax p{font-size:17px;line-height:1.65;color:var(--body);margin:0 0 14px}
.ax a{color:var(--link)}
.ax sup a{text-decoration:none;font-size:.75em;padding:0 1px}
.ax .key{background:var(--key);border-radius:10px;padding:16px 18px;margin:20px 0}
.ax .key b{display:block;font-size:12px;letter-spacing:.07em;text-transform:uppercase;color:var(--accent);margin-bottom:6px}
.ax .key p{margin:0;font-size:17px;color:var(--fg)}
.ax .fig{background:var(--panel);border-radius:10px;padding:20px 20px 14px;margin:22px 0}
.ax .fig h3{font-size:15px;margin:0 0 10px}
.ax .fig svg{display:block;max-width:100%;height:auto}
.ax .cap{font-size:13px;color:var(--muted);line-height:1.5;margin:10px 0 0}
.ax .steps{display:grid;gap:12px;margin:18px 0;padding:0;list-style:none;counter-reset:s}
.ax .steps li{display:grid;grid-template-columns:auto minmax(0,1fr);gap:4px 14px;align-items:start}
.ax .steps li::before{counter-increment:s;content:counter(s);width:28px;height:28px;border-radius:50%;background:var(--accent);color:var(--bg);font-weight:700;font-size:14px;display:flex;align-items:center;justify-content:center;grid-row:1 / span 2}
.ax .steps b{font-size:17px;color:var(--fg)}
.ax .steps span{font-size:16px;line-height:1.6;color:var(--body)}
.ax .limit{border:1px solid var(--rule);border-radius:10px;padding:16px 18px;margin:24px 0}
.ax .limit b{display:block;font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:8px}
.ax .limit ul{margin:0;padding-left:18px}
.ax .limit li{font-size:15px;line-height:1.6;color:var(--body);margin-bottom:6px}
.ax .faq h3{margin-top:20px}
.ax .src{font-size:13px;color:var(--muted);line-height:1.7;padding-left:22px}
.ax .src li{margin-bottom:6px}
.ax svg .grid{stroke:var(--rule);stroke-width:1}
.ax svg .grid.base{stroke:var(--muted);stroke-dasharray:4 4}
.ax svg .bar{fill:var(--bar)}
.ax svg .hot{fill:var(--hot)}
.ax svg .ref{fill:var(--ref)}
.ax svg .acc{fill:var(--accent)}
.ax svg .lab{font:12px var(--font);fill:var(--body)}
.ax svg .tick{font:11px var(--font);fill:var(--muted)}
.ax svg .val{font:600 14px var(--font);fill:var(--fg)}
.ax svg .note-t{font:600 12px var(--font);fill:var(--accent)}
.ax svg .arrow{stroke:var(--accent);stroke-width:2;fill:none}
.ax svg .gv{transform-box:fill-box;transform-origin:50% 100%}
.ax svg .gh{transform-box:fill-box;transform-origin:0 50%}
.ax .play svg .gv{animation:ax-gv .9s cubic-bezier(.2,.7,.2,1) both;animation-delay:var(--d,0s)}
.ax .play svg .gh{animation:ax-gh .9s cubic-bezier(.2,.7,.2,1) both;animation-delay:var(--d,0s)}
.ax .play svg .fade{animation:ax-fade .6s ease both;animation-delay:var(--d,1s)}
@keyframes ax-gv{from{transform:scaleY(0)}to{transform:scaleY(1)}}
@keyframes ax-gh{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes ax-fade{from{opacity:0}to{opacity:1}}
@media (prefers-reduced-motion:reduce){.ax .play svg .gv,.ax .play svg .gh,.ax .play svg .fade{animation:none}}
.ax svg .ln{fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.ax svg .ln.a{stroke:var(--accent)}
.ax svg .ln.b{stroke:var(--bar)}
.ax svg .dot{fill:var(--accent)}
.ax svg .dot.b{fill:var(--bar)}
.ax .play svg .draw{animation:ax-draw 1.6s ease both;animation-delay:var(--d,0s)}
@keyframes ax-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
.ax svg .draw{stroke-dasharray:1;stroke-dashoffset:0}
@media (prefers-reduced-motion:reduce){.ax .play svg .draw{animation:none}}
.ax .stage{margin-top:44px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--accent);font-weight:700;border-top:1px solid var(--rule);padding-top:14px}
.ax .stage + h2{margin-top:6px}
.ax svg .gc{transform-box:fill-box;transform-origin:50% 50%}
.ax .play svg .gc{animation:ax-gc .9s cubic-bezier(.2,.7,.2,1) both}
@keyframes ax-gc{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@media (prefers-reduced-motion:reduce){.ax .play svg .gc{animation:none}}
